import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const KINDS = [
  { kind: "w9", file: "w9.txt" },
  { kind: "insurance_certificate", file: "insurance_certificate.txt" },
  { kind: "contract", file: "contract.txt" },
] as const;

test("submit a vendor with all documents extracted", { tag: "@REV-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev Check"), category: "services", contact_email: "ops@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string; status: string };
  expect(vendor.status).toBe("draft");

  for (const { kind, file } of KINDS) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Wait for background extraction of every document.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as { kind: string; status: string }[];
        return KINDS.map(({ kind }) => docs.find((d) => d.kind === kind)?.status);
      },
      { timeout: 60_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const submitted = (await response.json()) as { status: string; submitted_at: string | null };
  expect(submitted.status).toBe("in_review");
  expect(submitted.submitted_at).not.toBeNull();

  const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(audit.status(), await audit.text()).toBe(200);
  const actions = ((await audit.json()) as { items: { action: string }[] }).items.map((e) => e.action);
  expect(actions, "audit trail").toContain("vendor.submitted");
});
